/* Matchday Masters: static, offline-friendly local-first prototype. */
const KEY='mdm-v1.6-session';const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const id=()=>crypto.randomUUID?.()||String(Date.now())+Math.random();const initial=()=>({club:null,players:[],matches:[],season:'2026/27'});let db;try{db=JSON.parse(localStorage.getItem(KEY))||initial()}catch{db=initial()}let page='home',modal=null,matchId=null,lastGoalUndo=null;const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(db));queueCloudSave()}catch{alert('Storage is full. Export a backup and free device storage.')}};const dateText=d=>new Date(d).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});const seasonNow=()=>{let d=new Date(),y=d.getFullYear();if(d.getMonth()<7)y--;return `${y}/${String(y+1).slice(2)}`};if(!db.season)db.season=seasonNow();const pBy=id=>db.players.find(p=>p.id===id);const name=id=>pBy(id)?.name||'Unknown player';const current=()=>db.matches.find(m=>m.id===matchId)||db.matches.find(m=>m.status==='live');const finalMatches=()=>db.matches.filter(m=>m.status==='finished');const events=m=>[...m.events].sort((a,b)=>a.minute-b.minute||a.order-b.order);const goals=m=>m.events.filter(e=>e.type==='goal'||e.type==='penalty-goal').length;const oppGoals=m=>m.events.filter(e=>e.type==='opponent-goal').length;const score=m=>`${goals(m)}–${oppGoals(m)}`;const result=m=>goals(m)>oppGoals(m)?'W':goals(m)<oppGoals(m)?'L':'D';const minute=t=>`${Math.floor(t/60)}'`;const elapsed=m=>m.elapsed+(m.runningSince?Math.max(0,Math.floor((Date.now()-m.runningSince)/1000)):0);const formatClock=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;const playerAppeared=(m,pid)=>m.starters.includes(pid)||m.events.some(e=>(e.type==='sub'&&e.on===pid||e.type==='pitch-add'&&e.player===pid));const playerStarts=pid=>finalMatches().filter(m=>m.starters.includes(pid)).length;const playerApps=pid=>finalMatches().filter(m=>playerAppeared(m,pid)).length;const playerGoals=(pid,season=null)=>finalMatches().filter(m=>!season||m.season===season).flatMap(m=>m.events).filter(e=>(e.type==='goal'||e.type==='penalty-goal')&&e.player===pid).length;const playerAssists=(pid,season=null)=>finalMatches().filter(m=>!season||m.season===season).flatMap(m=>m.events).filter(e=>e.assist===pid&&(e.type==='goal'||e.type==='penalty-goal')).length;const stats=()=>{const a=finalMatches().filter(m=>m.season===db.season);return {played:a.length,w:a.filter(m=>result(m)==='W').length,d:a.filter(m=>result(m)==='D').length,l:a.filter(m=>result(m)==='L').length,g:a.reduce((s,m)=>s+goals(m),0)}};
const seasonList=()=>[...new Set([db.season,...db.matches.map(m=>m.season).filter(Boolean)])].sort().reverse();
// Older versions could leave a statsSeason selection pointing to a season that no longer exists.
// Always fall back to the active season so the statistics page never silently shows unrelated zeros.
const selectedStatsSeason=()=>seasonList().includes(db.statsSeason)?db.statsSeason:db.season;
const seasonMatches=(season=db.season)=>finalMatches().filter(m=>m.season===season);
const playerSeasonStats=(pid,season=db.season)=>{const ms=seasonMatches(season),appearances=ms.filter(m=>playerAppeared(m,pid)).length,starts=ms.filter(m=>m.starters.includes(pid)).length,goals=playerGoals(pid,season),assists=playerAssists(pid,season);return {appearances,starts,goals,assists,hatTricks:ms.filter(m=>m.events.filter(e=>(e.type==='goal'||e.type==='penalty-goal')&&e.player===pid).length>=3).length,penalties:ms.flatMap(m=>m.events).filter(e=>e.type==='penalty-goal'&&e.player===pid).length,misses:ms.flatMap(m=>m.events).filter(e=>e.type==='penalty-miss'&&e.player===pid).length}};
const teamSeasonStats=(season=db.season)=>{const ms=seasonMatches(season),gf=ms.reduce((n,m)=>n+goals(m),0),ga=ms.reduce((n,m)=>n+oppGoals(m),0);let winning=0,unbeaten=0,bestWinning=0,bestUnbeaten=0;for(const m of [...ms].sort((a,b)=>a.date.localeCompare(b.date))){const r=result(m);winning=r==='W'?winning+1:0;unbeaten=r==='L'?0:unbeaten+1;bestWinning=Math.max(bestWinning,winning);bestUnbeaten=Math.max(bestUnbeaten,unbeaten)}return {played:ms.length,w:ms.filter(m=>result(m)==='W').length,d:ms.filter(m=>result(m)==='D').length,l:ms.filter(m=>result(m)==='L').length,gf,ga,gd:gf-ga,winPct:ms.length?Math.round(ms.filter(m=>result(m)==='W').length*100/ms.length):0,bestWinning,bestUnbeaten}};
const statTiles=items=>`<div class="grid">${items.map(([k,v])=>`<div class="panel"><span class="eyebrow">${esc(k)}</span><h1>${esc(v)}</h1></div>`).join('')}</div>`;
// Derived moments: recomputed from completed match history, never stored as stale totals.
const milestoneTargets=[1,5,10,25,50,100,200,250];
const momentCategory=x=>x.kind||'milestone';
const orderedMatches=()=>[...finalMatches()].sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.id).localeCompare(String(b.id)));
const milestones=()=>{const out=[];for(const p of db.players){let apps=0,goalsTotal=0,assistsTotal=0,streak=0,scoringStreak=0;const seasonGoals={};for(const m of orderedMatches()){
 const appeared=playerAppeared(m,p.id),started=m.starters.includes(p.id);
 streak=started?streak+1:0;
 if(appeared){apps++;if([1,10,25,50,100,200,250].includes(apps))out.push({key:`app-${p.id}-${apps}`,pid:p.id,kind:'appearance',title:apps===1?'Club debut':`${apps} club appearances`,desc:apps===1?`${p.name} made their club debut against ${m.opponent}.`:`${p.name} reached ${apps} club appearances.`,match:m.id,date:m.date})}
 if(started&&[5,10,20,25,50].includes(streak))out.push({key:`start-${p.id}-${streak}`,pid:p.id,kind:'streak',title:`${streak} consecutive starts`,desc:`${p.name} made ${streak} consecutive starts.`,match:m.id,date:m.date});
 const pg=events(m).filter(e=>(e.type==='goal'||e.type==='penalty-goal')&&e.player===p.id);
 const pa=events(m).filter(e=>(e.type==='goal'||e.type==='penalty-goal')&&e.assist===p.id);
 scoringStreak=pg.length?scoringStreak+1:0;
 if(pg.length>=3)out.push({key:`hat-${p.id}-${m.id}`,pid:p.id,kind:'hat-trick',title:pg.length===3?'Hat-trick hero':`${pg.length}-goal hero`,desc:`${p.name} scored ${pg.length} goals against ${m.opponent} (${pg.map(e=>minute(e.minute)).join(', ')}).`,match:m.id,date:m.date});
 if([3,5,10].includes(scoringStreak))out.push({key:`score-streak-${p.id}-${scoringStreak}-${m.id}`,pid:p.id,kind:'streak',title:`Scored in ${scoringStreak} straight matches`,desc:`${p.name} scored in ${scoringStreak} consecutive appearances in the match sequence.`,match:m.id,date:m.date});
 for(const e of pg){goalsTotal++;seasonGoals[m.season]=(seasonGoals[m.season]||0)+1;
 if([1,5,10,25,50,100,200].includes(goalsTotal))out.push({key:`goal-${p.id}-${goalsTotal}`,pid:p.id,kind:'goal',title:goalsTotal===1?'First club goal':`${goalsTotal} career goals`,desc:`${p.name} reached ${goalsTotal} career goals against ${m.opponent} in the ${minute(e.minute)} minute${e.assist?`, assisted by ${name(e.assist)}`:''}.`,match:m.id,date:m.date,minute:e.minute});
 if([5,10,20,25,50].includes(seasonGoals[m.season]))out.push({key:`sg-${p.id}-${m.season}-${seasonGoals[m.season]}`,pid:p.id,kind:'season',title:`${seasonGoals[m.season]} season goals`,desc:`${p.name} reached ${seasonGoals[m.season]} goals in ${m.season}.`,match:m.id,date:m.date,minute:e.minute})}
 for(const e of pa){assistsTotal++;if([1,5,10,25,50,100].includes(assistsTotal))out.push({key:`assist-${p.id}-${assistsTotal}`,pid:p.id,kind:'assist',title:assistsTotal===1?'First club assist':`${assistsTotal} career assists`,desc:`${p.name} recorded career assist number ${assistsTotal} against ${m.opponent}.`,match:m.id,date:m.date,minute:e.minute})}
 }}return out.sort((a,b)=>String(b.date).localeCompare(String(a.date))||String(b.match).localeCompare(String(a.match)))};
const achievable=()=>{const out=[];const recent=[...orderedMatches()].reverse();for(const p of db.players.filter(p=>p.active!==false)){const a=playerApps(p.id),g=playerGoals(p.id),sg=playerGoals(p.id,db.season),assists=playerAssists(p.id);
 if(!g)out.push({pid:p.id,kind:'goal',title:'First club goal',desc:`One goal would be ${p.name}'s first for the club.`});
 for(const n of [5,10,25,50,100,200])if(g===n-1)out.push({pid:p.id,kind:'goal',title:`${n} career goals`,desc:`One goal away from ${n} career goals.`});
 for(const n of [5,10,20,25,50])if(sg===n-1)out.push({pid:p.id,kind:'season',title:`${n} season goals`,desc:`One goal away from ${n} goals this season.`});
 for(const n of [1,10,25,50,100,200,250])if(a===n-1)out.push({pid:p.id,kind:'appearance',title:n===1?'Club debut':`${n} appearances`,desc:`Next appearance would be number ${n}.`});
 for(const n of [1,5,10,25,50])if(assists===n-1)out.push({pid:p.id,kind:'assist',title:n===1?'First club assist':`${n} career assists`,desc:`One assist away from ${n} career assists.`});
 let starts=0;for(const m of recent){if(m.starters.includes(p.id))starts++;else break}if([4,9,19,24,49].includes(starts))out.push({pid:p.id,kind:'streak',title:`${starts+1} consecutive starts`,desc:`Another start would make it ${starts+1} in a row.`});
 }return out};
const clubRecords=()=>{const ms=orderedMatches();if(!ms.length)return [];const players=db.players.map(p=>({p,goals:playerGoals(p.id),apps:playerApps(p.id),assists:playerAssists(p.id)}));const best=(key)=>players.filter(x=>x[key]>0).sort((a,b)=>b[key]-a[key])[0];const out=[];for(const [key,title,unit] of [['goals','All-time top scorer','goals'],['apps','Most club appearances','appearances'],['assists','Most career assists','assists']]){const x=best(key);if(x)out.push({title,value:`${x[key]} ${unit}`,desc:x.p.name})}const biggest=[...ms].sort((a,b)=>(goals(b)-oppGoals(b))-(goals(a)-oppGoals(a)))[0];if(biggest&&goals(biggest)>oppGoals(biggest))out.push({title:'Biggest victory',value:score(biggest),desc:`vs ${biggest.opponent} · ${dateText(biggest.date)}`,match:biggest.id});return out};
const pitchPlayers=m=>{const playing=new Set(m.starters);for(const e of m.events){if(e.type==='sub'){playing.delete(e.off);playing.add(e.on)}else if(e.type==='pitch-add')playing.add(e.player);else if(e.type==='pitch-remove')playing.delete(e.player)}return playing};
const opponentCount=m=>Math.max(0,(Number.isFinite(+m.opponentPlayers)?+m.opponentPlayers:+m.format)+m.events.reduce((n,e)=>n+(e.type==='opp-add'?1:e.type==='opp-remove'?-1:0),0));
const miniCards=(players,group)=>`<div class="pickgrid">${players.map(p=>`<button type="button" class="pickcard" data-pick="${group}" data-id="${p.id}">${card(p)}</button>`).join('')}</div>`;
const scoreboard=(m,live=false)=>{const ours=m.events.filter(e=>e.type==='goal'||e.type==='penalty-goal').sort((a,b)=>a.minute-b.minute),theirs=m.events.filter(e=>e.type==='opponent-goal').sort((a,b)=>a.minute-b.minute);return `<div class="panel broadcast-board"><div class="broadcast-row"><div class="broadcast-team">${esc(db.club.name)}</div><div class="broadcast-score">${goals(m)}<span>–</span>${oppGoals(m)}</div><div class="broadcast-team">${esc(m.opponent)}</div></div><div class="broadcast-goals"><div>${ours.map(e=>`<div>⚽ ${esc(name(e.player))} ${minute(e.minute)}${e.type==='penalty-goal'?' (P)':''}</div>`).join('')}</div><div class="broadcast-mid">${live?`<div class="clock" id="clock">${formatClock(elapsed(m))}</div>`:'<span class="pill">FULL TIME</span>'}</div><div>${theirs.map(e=>`<div>⚽ ${minute(e.minute)}</div>`).join('')}</div></div><div class="broadcast-bottom"><span class="pill">${live?(m.phase==='pre'?'AWAITING KICK OFF':m.phase==='half-time'?'HALF TIME':m.half===1?'FIRST HALF':'SECOND HALF'):esc(m.season)}</span><span class="pill">👥 ${pitchPlayers(m).size} PLAYING vs ${opponentCount(m)} PLAYING</span></div>${live?`<div class="match-controls"><button class="button" data-action="phase">${m.phase==='pre'?'⚽ KICK OFF':m.phase==='half-time'?'▶ START 2ND HALF':m.half===1?'⏸ HALF TIME':'🏁 FULL TIME'}</button><button class="ghost" data-action="adjust">⏱ ADJUST CLOCK</button></div>`:''}</div>`};
const card=(p,gold=false)=>`<div class="playercard ${gold?'gold':''}"><div class="crest">⚽ ${esc(db.club?.name||'MATCHDAY MASTERS')}</div><div class="card-art"><span class="card-rays"></span><div class="jersey number">${esc(p.number||'—')}</div><div class="card-position">${esc(p.position||'PLAYER')}</div></div><div class="card-identity"><div class="pname">${esc(p.name)}</div><div class="sig">${esc(p.name)}</div></div><div class="card-foot">${gold?'★ MILESTONE EDITION ★':'MATCHDAY MASTERS'}</div></div>`;
const header=()=>page==='live'?`<header class="topbar live-topbar"><button class="ghost live-nav-home" data-go="home">← HOME</button><div class="live-heading"><strong>LIVE MATCH</strong><span id="cloud-status" class="cloud-status">🔴 CONNECTING…</span></div><button class="ghost live-nav-settings" data-go="settings" aria-label="Settings" title="Settings">⚙</button></header>`:`<header class="topbar"><div class="brand"><img src="icon.svg" alt="">MATCHDAY MASTERS</div><div class="row"><span id="cloud-status" class="cloud-status">🔴 CONNECTING…</span><button class="ghost" data-go="settings">⚙ Settings</button></div></header>`;const shell=(html)=>`<main class="shell">${header()}${html}<footer class="footer">EVERY MATCH · EVERY MOMENT · EVERY MEMORY</footer></main>`;const back=()=>`<button class="ghost" data-go="home">← Home</button>`;const title=(s,sub='')=>`<div class="section">${back()}<h2 style="margin-top:16px">${s}</h2>${sub?`<p class="muted">${sub}</p>`:''}</div>`;
// Reset scroll only when entering a different screen, not when logging an event.
let lastRenderedScreen = null;
function resetScreenScroll(){
  const reset=()=>{
    window.scrollTo(0,0);
    document.documentElement.scrollTop=0;
    document.body.scrollTop=0;
    const root=document.getElementById('app');
    if(root && root.scrollTop)root.scrollTop=0;
  };
  reset();
  requestAnimationFrame(()=>{reset();requestAnimationFrame(reset)});
  setTimeout(reset,80);
}
function render(){
  const screenKey=page+((page==='live'||page==='report'||page==='player')?':'+(matchId||''):'');
  const enteredNewScreen=screenKey!==lastRenderedScreen;
  lastRenderedScreen=screenKey;
  let html;if(!db.club){html=`<div class="splash"><div><img class="logo" src="icon.svg" alt="Matchday Masters"><div class="eyebrow">THE CLUB STARTS HERE</div><h1>MATCHDAY<br><span style="color:var(--lime)">MASTERS</span></h1><p>Every match. Every moment. Every memory.</p><button class="button" data-go="setup">CREATE YOUR CLUB →</button></div></div>`;if(page==='setup')html=shell(`<div class="hero"><span class="eyebrow">WELCOME TO MATCHDAY MASTERS</span><h1>CREATE YOUR CLUB</h1><p class="muted">Start from scratch. You can change everything later.</p></div><section class="panel section"><form id="setupForm" class="form"><label class="field">Club name<input name="name" required maxlength="70" placeholder="Your club name"></label><label class="field">Season<input name="season" required maxlength="20" value="${esc(seasonNow())}"></label><label class="field">Match format<select name="format"><option value="5">5v5</option><option value="7">7v7</option><option value="9" selected>9v9</option><option value="11">11v11</option></select></label><label class="field">Minutes per half<input name="half" type="number" min="5" max="90" value="30" required></label><button class="button">CREATE CLUB →</button></form></section>`)}else if(page==='home'){const s=stats();const live=db.matches.find(m=>m.status==='live');html=shell(`<div class="hero"><span class="eyebrow">${esc(db.season)} · YOUR CLUB</span><h1>${esc(db.club.name.toUpperCase())}</h1><p>YOUR STORY IS WRITTEN ON THE PITCH.</p><div class="stats"><div class="stat"><b>${s.played}</b><span class="small">PLAYED</span></div><div class="stat"><b>${s.w}</b><span class="small">WINS</span></div><div class="stat"><b>${s.d}</b><span class="small">DRAWS</span></div><div class="stat"><b>${s.l}</b><span class="small">LOSSES</span></div></div>${live?`<div class="recovery-banner" role="status"><strong>⚽ MATCH IN PROGRESS</strong><span>${esc(db.club.name)} ${score(live)} ${esc(live.opponent)} · ${live.phase==='half-time'?'HALF TIME':live.phase==='pre'?'AWAITING KICK OFF':live.phase==='second'?'SECOND HALF':'FIRST HALF'} · <span data-recovery-clock>${formatClock(elapsed(live))}</span></span><small>${cloud.dirty?'Saved on this device — awaiting cloud sync':'Resume your unfinished match below'}</small></div>`:''}<button class="button" data-go="${live?'live':'create'}">${live?'⏱ RESUME LIVE MATCH':'⚽ CREATE MATCH'} →</button></div><h2 class="section">CLUB DASHBOARD</h2><div class="grid"><button class="tile" data-go="achievable"><span class="emoji">🎯</span><h3>ACHIEVABLE MOMENTS</h3><span class="muted">${achievable().length} milestones within reach</span></button><button class="tile" data-go="history"><span class="emoji">📈</span><h3>FORM HISTORY</h3><span class="muted">${finalMatches().slice(-5).map(result).join(' · ')||'Your results appear here'}</span></button><button class="tile" data-go="season"><span class="emoji">🏆</span><h3>SEASON STATS</h3><span class="muted">${s.g} goals · ${s.played} matches</span></button><button class="tile" data-go="squad"><span class="emoji">🃏</span><h3>PLAYER STATS & SQUAD</h3><span class="muted">${db.players.length} players registered</span></button><button class="tile" data-go="moments"><span class="emoji">✨</span><h3>ACHIEVED MOMENTS</h3><span class="muted">${milestones().length} memories collected</span></button><button class="tile" data-go="settings"><span class="emoji">⚙️</span><h3>CLUB SETTINGS</h3><span class="muted">Manage club & backups</span></button></div>`)}else if(page==='squad'){html=shell(`${title('SQUAD & PLAYER STATS','Every player gets their own trading card, complete with an automatic script signature.')}<button class="button" data-action="addPlayer">+ ADD PLAYER</button><p class="hint">Add as many players as you need. You can edit a card and return here at any time.</p><div class="cardgrid section">${db.players.map(p=>`<button class="cardbutton" data-player="${p.id}">${card(p)}</button>`).join('')}</div>${db.players.length?'':'<div class="empty">No players yet. Add your first player to create a card.</div>'}`)}else if(page==='player'){const p=pBy(matchId);if(!p){page='squad';return render()}const a=finalMatches().filter(m=>playerAppeared(m,p.id));html=shell(`${title('PLAYER PROFILE')}<div class="grid"><div style="max-width:260px">${card(p)}</div><div class="panel"><h2>${esc(p.name)}</h2><p class="muted">#${esc(p.number)} · ${esc(p.position||'Player')}</p><div class="stats"><div class="stat"><b>${playerApps(p.id)}</b>Appearances</div><div class="stat"><b>${playerStarts(p.id)}</b>Starts</div><div class="stat"><b>${playerGoals(p.id)}</b>Goals</div><div class="stat"><b>${playerAssists(p.id)}</b>Assists</div></div><button class="ghost" data-action="editPlayer" data-id="${p.id}">Edit player</button> <button class="ghost" data-action="exportCard" data-id="${p.id}">Export card SVG</button></div></div><h2 class="section">PLAYER MOMENTS</h2>${momentList(milestones().filter(x=>x.pid===p.id))}<h2 class="section">MATCHES</h2>${matchList(a)}`)}else if(page==='settings'){html=shell(`${title('CLUB SETTINGS')}<div class="panel"><form id="settingsForm" class="form"><label class="field">Club name<input name="name" required value="${esc(db.club.name)}"></label><label class="field">Active season<select name="season">${seasonList().map(y=>`<option value="${esc(y)}" ${y===db.season?'selected':''}>${esc(y)}</option>`).join('')}</select></label><button class="ghost" type="button" id="newSeason">+ CREATE NEW SEASON</button><label class="field">Default match format<select name="format">${[5,7,9,11].map(n=>`<option value="${n}" ${+db.club.format===n?'selected':''}>${n}v${n}</option>`).join('')}</select></label><label class="field">Minutes per half<input name="half" type="number" min="5" max="90" value="${db.club.half}" required></label><button class="button">SAVE SETTINGS</button></form></div><h2 class="section">ACCOUNT</h2><div class="panel"><p class="muted">Signed in: ${esc(cloud.user?.email||'')}</p><button class="ghost" id="cloud-signout">SIGN OUT</button></div><h2 class="section">CLOUD HEALTH</h2><div class="panel"><p id="cloud-health-detail" class="muted">Checking sync state…</p><div class="row"><button class="ghost" type="button" id="cloud-check">CHECK CLOUD</button><button class="ghost" type="button" id="cloud-retry">RETRY SYNC</button><button class="ghost" type="button" id="mirror-refresh">CHECK STRUCTURED STORAGE</button></div><p class="hint">Structured records are updated transactionally on every confirmed cloud save. A green sync indicator means this device's latest snapshot was accepted. It does not mean other open devices update automatically. Use one recording device per match.</p></div><h2 class="section">RELEASE CHECKS</h2><div class="panel"><p class="muted" id="release-check-results">Checking match records…</p><button class="ghost" id="run-release-checks" type="button">RUN DATA CHECKS</button><p class="hint">Read-only checks for duplicate IDs, missing players, invalid match events and incorrect lineup references. These do not replace a full security audit.</p></div><h2 class="section">DATA & BACKUPS</h2><div class="panel"><p class="warning">Offline edits are saved on this device first. Wait for CLOUD SYNCED before signing out or switching devices. Export backups regularly. If CLOUD CONFLICT appears, export a backup before reloading.</p><div class="row"><button class="button" data-action="backup">⬇ EXPORT BACKUP</button><label class="ghost" style="cursor:pointer">⬆ IMPORT BACKUP<input id="importFile" type="file" accept="application/json,.json" hidden></label></div><hr class="divider"><button class="danger" data-action="reset">RESET ALL DATA</button><p class="hint">Reset deletes this device's club, players, matches and moments.</p></div>`)}else if(page==='create'){if(db.players.filter(p=>p.active!==false).length===0)html=shell(`${title('CREATE MATCH')}<div class="empty">Add your squad first so you can select a starting lineup.<br><br><button class="button" data-go="squad">ADD PLAYERS</button></div>`);else html=shell(`${title('CREATE MATCH','Set up the fixture and choose your starting players.')}<form id="matchForm" class="form panel"><label class="field">Opponent<input name="opponent" required maxlength="80" placeholder="Opposition club"></label><label class="field">Match date<input name="date" type="date" value="${new Date().toLocaleDateString('en-CA')}" required></label><label class="field">Competition<input name="competition" placeholder="League / Friendly / Cup"></label><label class="field">Venue<select name="venue"><option>Home</option><option>Away</option><option>Neutral</option></select></label><label class="field">Format<select name="format">${[5,7,9,11].map(n=>`<option value="${n}" ${+db.club.format===n?'selected':''}>${n}v${n}</option>`).join('')}</select></label><label class="field">Minutes per half<input name="half" type="number" min="5" max="90" value="${db.club.half}" required></label><div><h3>STARTING LINEUP</h3><p class="muted small">Select the players starting the match. You can record substitutes later.</p><div class="selectgrid" id="lineup">${db.players.filter(p=>p.active!==false).map(p=>`<button type="button" class="ghost" data-select="${p.id}">#${esc(p.number)} ${esc(p.name)}</button>`).join('')}</div><p class="hint" id="lineupCount">0 selected</p></div><button class="button">⚽ CREATE & START MATCH</button></form>`)}else if(page==='live'){const m=current();if(!m){page='home';return render()}matchId=m.id;html=shell(`<div class="live-fixture-meta">${esc(m.competition||'Matchday')} · ${esc(m.venue)} · ${dateText(m.date)}</div>${scoreboard(m,true)}<h2 class="section">RECORD EVENT</h2><div class="eventgrid"><button class="button" data-event="goal">⚽ OUR GOAL</button><button class="ghost" data-event="penalty">🥅 PENALTY</button><button class="ghost" data-event="opponent-goal">🔴 OPPONENT GOAL</button><button class="ghost" data-event="sub">🔄 SUBSTITUTION</button><button class="ghost" data-event="pitch">👥 ADJUST PLAYERS</button><button class="ghost" data-action="undo">↶ UNDO LAST</button></div><h2 class="section">MATCH TIMELINE</h2><div class="list">${timeline(m)}</div><div class="section"><p class="hint">The main match control above ends the game after the second half.</p></div>`)}else if(page==='history'){html=shell(`${title('FORM HISTORY','Tap a result to open its full match report.')}${matchList([...finalMatches()].reverse())}`)}else if(page==='report'){const m=db.matches.find(m=>m.id===matchId);if(!m){page='history';return render()}html=shell(`${title('MATCH REPORT',`${dateText(m.date)} · ${esc(m.competition||'Match')} · ${esc(m.venue)}`)}${scoreboard(m,false)}<div class="section"><span class="pill ${result(m)==='W'?'win':result(m)==='L'?'loss':'draw'}">${result(m)==='W'?'WIN':result(m)==='L'?'LOSS':'DRAW'}</span></div><h2 class="section">MATCH TIMELINE</h2><div class="list">${timeline(m)}</div><h2 class="section">STARTING LINEUP</h2><div class="panel">${m.starters.map(pid=>`<span class="pill" style="margin:4px">${esc(name(pid))}</span>`).join('')}</div><h2 class="section">MOMENTS UNLOCKED</h2>${momentList(milestones().filter(x=>x.match===m.id))}<div class="section"><button class="ghost" data-action="deleteMatch" data-id="${m.id}">Delete match</button></div>`)}else if(page==='season'){const selected=selectedStatsSeason();const ss=teamSeasonStats(selected);html=shell(`${title('SEASON STATISTICS',esc(selected))}<label class="field" style="max-width:340px">View season<select id="statsSeason">${seasonList().map(y=>`<option value="${esc(y)}" ${y===selected?'selected':''}>${esc(y)}</option>`).join('')}</select></label>${statTiles([['MATCHES',ss.played],['WINS',ss.w],['DRAWS',ss.d],['LOSSES',ss.l],['GOALS FOR',ss.gf],['GOALS AGAINST',ss.ga],['GOAL DIFFERENCE',ss.gd],['WIN RATE',ss.winPct+'%'],['LONGEST WIN STREAK',ss.bestWinning],['LONGEST UNBEATEN RUN',ss.bestUnbeaten]])}<h2 class="section">PLAYER STATISTICS</h2><div class="list">${[...db.players].sort((a,b)=>playerGoals(b.id,selected)-playerGoals(a.id,selected)).map(p=>{const x=playerSeasonStats(p.id,selected);return `<button class="listitem" data-player="${p.id}"><span>${esc(p.name)}</span><b>${x.appearances} apps · ${x.starts} starts · ${x.goals} goals · ${x.assists} assists</b></button>`}).join('')}</div>`)}else if(page==='achievable'){html=shell(`${title('ACHIEVABLE MOMENTS','Milestones your players could reach in their next match.')}${momentList(achievable(),true)}`)}else if(page==='moments'){html=shell(`${title('ACHIEVED MOMENTS','Your club’s growing collection of memories.')}<label class="field" style="max-width:350px;margin-bottom:18px">Filter by player<select id="momentFilter"><option value="">All players</option>${db.players.map(p=>`<option value="${p.id}" ${matchId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div id="momentResults">${momentList(milestones().filter(x=>!matchId||x.pid===matchId))}</div><h2 class="section">CLUB RECORDS</h2>${recordList()}`)}else{page='home';return render()}$('#app').innerHTML=html;bind();if(typeof refreshCloudStatus==='function')refreshCloudStatus();if(enteredNewScreen)resetScreenScroll();}
function momentIcon(kind){
 const common='viewBox="0 0 120 120" width="100" height="100" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"';
 const ball='<circle cx="60" cy="60" r="24" stroke="currentColor" stroke-width="4"/><path d="M60 45l13 10-5 15H52l-5-15zM60 36v9M36 54l11 1M73 55l11-1M52 70l-9 13M68 70l9 13" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/>';
 const shield='<path d="M60 12L98 27v32c0 25-15 42-38 51C37 101 22 84 22 59V27z" stroke="currentColor" stroke-width="4"/><path d="M38 35h44" stroke="currentColor" stroke-opacity=".45" stroke-width="2"/>';
 const star='<path d="M60 12l9 28 29 0-23 17 9 28-24-17-24 17 9-28-23-17h29z" stroke="currentColor" stroke-width="4" stroke-linejoin="round"/>';
 let art;
 switch(kind){
 case 'hat-trick': art='<circle cx="60" cy="33" r="19" stroke="currentColor" stroke-width="4"/><circle cx="35" cy="76" r="19" stroke="currentColor" stroke-width="4"/><circle cx="85" cy="76" r="19" stroke="currentColor" stroke-width="4"/><path d="M60 23l6 5-2 7h-8l-2-7zM35 66l6 5-2 7h-8l-2-7zM85 66l6 5-2 7h-8l-2-7z" fill="currentColor"/>';break;
 case 'appearance':art=shield+'<path d="M45 54h30v18H45zM50 54V44h20v10" stroke="currentColor" stroke-width="3"/><path d="M60 34v-9" stroke="currentColor" stroke-width="3"/>';break;
 case 'streak':art='<path d="M62 10c6 24-12 28-8 47 10-6 17-17 18-28 28 26 27 57 9 73-13 11-32 12-46 0C13 83 28 52 44 39c-1 18 4 23 8 27-4-20 13-35 10-56z" stroke="currentColor" stroke-width="4"/><path d="M59 65c-3 15-17 22-7 35 6 7 18 5 22-2 7-12-6-23-7-33" stroke="currentColor" stroke-width="3"/>';break;
 case 'assist':art='<circle cx="34" cy="77" r="19" stroke="currentColor" stroke-width="4"/><path d="M34 58l9 7-3 11H28l-4-11zM16 72l12 4m21-4-9 4M24 91l4-15m22 15-10-15M61 76c14-2 27-13 31-29M78 45l15 1 1 15" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>';break;
 case 'season':art=shield+ball.replaceAll('60','60');break;
 case 'goal':art='<path d="M16 82V31h88v51M16 31l18 16 16-16 16 16 18-16 20 16M16 82h88" stroke="currentColor" stroke-width="3" stroke-opacity=".6"/>'+ball;break;
 default:art=star;
 }
 return `<svg ${common}>${art}</svg>`;
}
function momentList(arr,potential=false){return arr.length?`<div class="moment-grid">${arr.map(x=>{const p=pBy(x.pid);const label=potential?'WITHIN REACH':'MEMORY UNLOCKED';const link=!potential&&x.match&&db.matches.some(m=>m.id===x.match);return `<${link?'button':'div'} ${link?'type="button" data-report="'+esc(x.match)+'"':''} class="moment-tile ${potential?'moment-future':'moment-achieved'}" ${link?'aria-label="View match for '+esc(x.title)+'"':''}><div class="moment-top"><span class="eyebrow">${potential?'◎':'✦'} ${label}</span><span class="moment-type">${esc(momentCategory(x).replace('-', ' ').toUpperCase())}</span></div><div class="moment-feature"><div class="moment-identity">${p?`<div class="moment-player-name">${esc(p.name)}</div><div class="moment-number">#${esc(p.number||'—')}</div>`:''}</div><div class="moment-graphic">${momentIcon(x.kind)}</div></div><div class="moment-info"><h3>${esc(x.title)}</h3><p>${esc(x.desc)}</p>${potential?'':`<span class="matchtag">${dateText(x.date)}${link?' · VIEW MATCH →':''}</span>`}</div></${link?'button':'div'}>`}).join('')}</div>`:'<div class="empty">Nothing here yet. Keep recording matches to build your club history.</div>'}

function recordList(){const a=clubRecords();return a.length?`<div class="grid">${a.map(x=>`<${x.match?'button':'div'} class="tile" ${x.match?`data-report="${esc(x.match)}"`:''}><span class="eyebrow">🏆 CLUB RECORD</span><h3>${esc(x.title)}</h3><strong>${esc(x.value)}</strong><p class="muted">${esc(x.desc)}</p></${x.match?'button':'div'}>`).join('')}</div>`:'<div class="empty">Complete matches to establish club records.</div>'}
function matchList(arr){return arr.length?`<div class="list">${arr.map(m=>`<button class="listitem" data-report="${m.id}"><span><span class="pill ${result(m)==='W'?'win':result(m)==='L'?'loss':'draw'}">${result(m)}</span> &nbsp; ${esc(m.opponent)}<br><small class="muted">${dateText(m.date)}</small></span><b class="nowrap">${score(m)} →</b></button>`).join('')}</div>`:'<div class="empty">No completed matches yet.</div>'}function timeline(m){return events(m).length?events(m).map(e=>`<div class="event"><time>${minute(e.minute)}</time>${e.type==='goal'?'⚽ GOAL — '+esc(name(e.player))+(e.assist?' · Assist: '+esc(name(e.assist)):''):e.type==='penalty-goal'?'🥅 PENALTY SCORED — '+esc(name(e.player)):e.type==='penalty-miss'?'🥅 PENALTY MISSED — '+esc(name(e.player)):e.type==='opponent-goal'?'🔴 OPPONENT GOAL':e.type==='sub'?'🔄 '+esc(name(e.off))+' OFF · '+esc(name(e.on))+' ON':e.type==='pitch-add'?'👥 '+esc(name(e.player))+' added to pitch':e.type==='pitch-remove'?'👥 '+esc(name(e.player))+' left pitch':e.type==='opp-add'?'👥 Opposition player added':e.type==='opp-remove'?'👥 Opposition player removed':e.type==='add'?'➕ '+esc(name(e.player))+' added':'EVENT'}</div>`).join(''):'<div class="empty">Events will appear here as you record them.</div>'}
function eventFeedback(message,kind='normal',player=null,undo=false){toast('✓ '+message);if(navigator.vibrate)navigator.vibrate([65,35,95]);const flash=document.createElement('div');flash.className='event-flash '+(kind==='goal'?'goal-flash':kind==='opponent'?'opponent-flash':'');flash.innerHTML=kind==='goal'?`<div class="celebration"><h1>⚽ GOOOOAL!</h1>${player?card(player):''}<h2>${esc(message)}</h2>${undo?'<button type="button" class="undo-goal" id="undoGoal">↶ UNDO GOAL</button>':''}</div>`:kind==='opponent'?'🔴 OPPONENT GOAL':'✓ '+esc(message);document.body.append(flash);let timer=setTimeout(()=>{flash.remove();if(undo)lastGoalUndo=null},kind==='goal'?2600:950);if(undo){flash.style.pointerEvents='auto';flash.querySelector('#undoGoal').onclick=()=>{clearTimeout(timer);flash.remove();const u=lastGoalUndo;lastGoalUndo=null;const match=db.matches.find(x=>x.id===u?.matchId);if(!match)return;const index=match.events.findIndex(e=>e.id===u.eventId);if(index<0)return;match.events.splice(index,1);save();render();toast('Goal undone')}}}
function toast(s){$('#toast').textContent=s;$('#toast').style.cssText='position:fixed;bottom:22px;left:50%;transform:translateX(-50%);background:#b8ff3b;color:#07111f;padding:12px 18px;border-radius:12px;font-weight:800;z-index:100;box-shadow:0 10px 30px #0009';setTimeout(()=>$('#toast').style.display='none',2500);$('#toast').style.display='block'}function go(s){page=s;matchId=null;render()}function show(html){modal=document.createElement('div');modal.className='overlay';modal.innerHTML=`<div class="modal">${html}</div>`;document.body.append(modal);modal.addEventListener('click',e=>{if(e.target===modal||e.target.closest('[data-close]'))close()})}function close(){modal?.remove();modal=null}function addPlayer(pid=null){const p=pBy(pid);show(`<div class="row spread"><h2>${p?'EDIT PLAYER':'ADD PLAYER'}</h2><button class="ghost" data-close>✕</button></div><form id="playerForm" class="form"><label class="field">Player name<input name="name" maxlength="65" required value="${esc(p?.name||'')}" placeholder="First and last name"></label><label class="field">Shirt number<input name="number" maxlength="5" required value="${esc(p?.number||'')}" placeholder="9"></label><label class="field">Position (optional)<input name="position" maxlength="30" value="${esc(p?.position||'')}" placeholder="Forward"></label>${p?`<label class="field">Squad status<select name="active"><option value="yes" ${p.active!==false?'selected':''}>Active</option><option value="no" ${p.active===false?'selected':''}>Inactive</option></select></label>`:''}<p class="hint">The player card and decorative script signature are created automatically.</p><button class="button">${p?'SAVE CHANGES':'SAVE & ADD ANOTHER'}</button><button type="button" class="ghost" data-close>DONE — BACK TO SQUAD</button></form>`);$('#playerForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(p)Object.assign(p,{name:f.get('name').trim(),number:f.get('number').trim(),position:f.get('position').trim(),active:f.get('active')==='yes'});else {const np={id:id(),name:f.get('name').trim(),number:f.get('number').trim(),position:f.get('position').trim(),active:true};db.players.push(np)}save();close();render();toast('Player saved');if(!p&&page==='squad')addPlayer()}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-report]');if(!button)return;const m=db.matches.find(m=>m.id===button.dataset.report);if(!m)return;matchId=m.id;page='report';render();});
function runReleaseChecks(){
 const warnings=[];const playerIds=new Set(),matchIds=new Set();
 for(const p of db.players){if(!p.id||playerIds.has(p.id))warnings.push('Duplicate or missing player ID');playerIds.add(p.id)}
 for(const m of db.matches){
  if(!m.id||matchIds.has(m.id))warnings.push('Duplicate or missing match ID');matchIds.add(m.id);
  if(!m.season)warnings.push('Match missing season: '+(m.opponent||'unknown'));
  const seen=new Set();for(const pid of m.starters||[])if(!playerIds.has(pid))warnings.push('Starting player missing from squad');
  for(const e of m.events||[]){
   if(!e.id||seen.has(e.id))warnings.push('Duplicate or missing event ID');seen.add(e.id);
   if(!Number.isFinite(Number(e.minute))||Number(e.minute)<0)warnings.push('Invalid event time');
   for(const key of ['player','assist','off','on'])if(e[key]&&!playerIds.has(e[key]))warnings.push('Event refers to missing player');
   if(e.assist&&e.player===e.assist)warnings.push('Goalscorer cannot assist themselves');
  }
 }
 const el=document.getElementById('release-check-results');if(el)el.textContent=warnings.length?'⚠ '+[...new Set(warnings)].join(' · '):'✓ Data consistency checks passed · '+db.players.length+' players · '+db.matches.length+' matches · '+db.matches.reduce((n,m)=>n+(m.events||[]).length,0)+' events';
 return warnings;
}
let lineup=new Set();function bind(){if($('#run-release-checks'))$('#run-release-checks').onclick=runReleaseChecks;if($('#release-check-results'))runReleaseChecks();if($('#cloud-signout'))$('#cloud-signout').onclick=cloudSignOut;if($('#cloud-check'))$('#cloud-check').onclick=checkCloudHealth;if($('#mirror-refresh'))$('#mirror-refresh').onclick=async()=>{await refreshStructuredMirror();updateCloudHealth()};if($('#cloud-retry'))$('#cloud-retry').onclick=()=>{cloudStatus('🟡 CHECKING CLOUD…');cloudFlush().then(checkCloudHealth)};if($('#cloud-health-detail'))updateCloudHealth();document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>{matchId=b.dataset.player;page='player';render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id));document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>eventModal(b.dataset.event));$('#setupForm')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);db.club={name:f.get('name').trim(),format:+f.get('format'),half:+f.get('half')};db.season=f.get('season').trim();db.statsSeason=db.season;save();go('squad')});$('#newSeason')?.addEventListener('click',()=>{if(db.matches.some(m=>m.status==='live'))return alert('Finish the live match before changing seasons.');const y=prompt('New season (for example 2027/28):');if(y===null)return;const value=y.trim();if(!/^\d{4}\/\d{2}$/.test(value))return alert('Use YYYY/YY format, for example 2027/28.');if(seasonList().includes(value))return alert('That season already exists. Select it from the list.');db.season=value;db.statsSeason=value;save();render();toast('New season created. Career records retained.')});$('#settingsForm')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);db.club={name:f.get('name').trim(),format:+f.get('format'),half:+f.get('half')};db.season=f.get('season').trim();db.statsSeason=db.season;save();toast('Settings saved');render()});if($('#matchForm')){lineup=new Set();document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{lineup.has(b.dataset.select)?lineup.delete(b.dataset.select):lineup.add(b.dataset.select);b.classList.toggle('selected');$('#lineupCount').textContent=`${lineup.size} selected`});$('#matchForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!lineup.size)return alert('Select at least one starting player.');if(lineup.size>+f.get('format'))return alert(`You can select at most ${f.get('format')} starters for this format.`);if(db.matches.some(m=>m.status==='live'))return alert('Finish your live match first.');let m={id:id(),opponent:f.get('opponent').trim(),opponentPlayers:+f.get('format'),date:f.get('date'),competition:f.get('competition').trim(),venue:f.get('venue'),format:+f.get('format'),halfMinutes:+f.get('half'),season:db.season,starters:[...lineup],events:[],elapsed:0,runningSince:null,half:1,phase:'pre',status:'live'};db.matches.push(m);save();matchId=m.id;page='live';render()}}$('#statsSeason')?.addEventListener('change',e=>{db.statsSeason=e.target.value;render()});$('#momentFilter')?.addEventListener('change',e=>{matchId=e.target.value;$('#momentResults').innerHTML=momentList(milestones().filter(x=>!matchId||x.pid===matchId))});$('#importFile')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!data.club||!Array.isArray(data.players)||!Array.isArray(data.matches))throw Error('Invalid backup format');if(!confirm('Replace ALL current club data with this backup?'))return;db=data;save();go('home');toast('Backup imported')}catch(err){alert('Could not import backup: '+err.message)}})}
function action(type,pid){const m=current();if(type==='addPlayer')return addPlayer();if(type==='editPlayer')return addPlayer(pid);if(type==='backup'){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='matchday-masters-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);return}if(type==='reset'){if(confirm('Delete ALL club data from this account (including cloud after sync)?')&&confirm('This cannot be undone without a backup. Delete everything?')){db=initial();save();go('home')}return}if(type==='exportCard')return exportCard(pBy(pid));if(type==='deleteMatch'){if(confirm('Delete this match and recalculate statistics and memories?')){db.matches=db.matches.filter(x=>x.id!==pid);save();go('history')}return}if(!m)return;if(type==='phase'){if(m.phase==='pre'){m.phase='first';m.runningSince=Date.now();toast('Kick off!')}else if(m.phase==='half-time'){m.phase='second';m.half=2;m.runningSince=Date.now();toast('Second half started!')}else if(m.half===1){m.elapsed=elapsed(m);m.runningSince=null;m.phase='half-time';toast('Half time')}else {return action('finish')}save();render();return}if(type==='pause'){if(m.runningSince){m.elapsed=elapsed(m);m.runningSince=null}else m.runningSince=Date.now()}if(type==='half'){if(m.half===1){m.elapsed=elapsed(m);m.runningSince=null;m.half=2;if(confirm('Start second half now?'))m.runningSince=Date.now()}else return alert('Already in second half. Use pause/resume as needed.')}if(type==='adjust'){const v=prompt('Set elapsed match time in MM:SS format',formatClock(elapsed(m)));if(v!==null){const parts=v.match(/^(\d{1,3}):(\d{2})$/);if(!parts||+parts[2]>59)return alert('Use MM:SS, e.g. 32:15');m.elapsed=+parts[1]*60+(+parts[2]);m.runningSince=m.runningSince?Date.now():null}}if(type==='undo'){if(!m.events.length)return toast('No events to undo');if(confirm('Remove the last recorded event?'))m.events.pop()}if(type==='finish'){if(!confirm('End the match and save the final result?'))return;m.elapsed=elapsed(m);m.runningSince=null;m.status='finished';m.phase='full-time';save();matchId=m.id;page='report';render();return}save();render()}
function eventModal(type){
 const m=current();if(!m)return;
 if(m.phase==='pre'||m.phase==='half-time'){toast('Start the half before recording events');return}
 const playing=pitchPlayers(m),active=db.players.filter(p=>p.active!==false),on=active.filter(p=>playing.has(p.id)),bench=active.filter(p=>!playing.has(p.id));
 const push=e=>{if(!m||m.status!=='live')return;const event={id:id(),minute:elapsed(m),order:Date.now()+m.events.length,...e};m.events.push(event);save();close();render()};
 const selectable=(group,players)=>{document.querySelectorAll(`[data-pick="${group}"]`).forEach(b=>b.onclick=()=>{const multi=group==='off'||group==='on';if(!multi)document.querySelectorAll(`[data-pick="${group}"]`).forEach(x=>x.classList.remove('selected'));b.classList.toggle('selected');if(!multi)b.classList.add('selected')})};
 const selected=group=>[...document.querySelectorAll(`[data-pick="${group}"].selected`)].map(b=>b.dataset.id);
 if(type==='opponent-goal'){push({type});eventFeedback('Opponent goal recorded','opponent');return}
 if(type==='goal'){
  if(!on.length)return alert('There are no registered players currently on the pitch.');
  const goalPicker=(stage,scorer)=>{
   if(stage==='scorer'){
    show(`<div class="row spread"><h2>⚽ SELECT GOALSCORER</h2><button class="ghost" data-close>✕</button></div><p class="muted">Tap a player currently on the pitch.</p>${miniCards(on,'scorer')}`);
    modal.querySelectorAll('[data-pick="scorer"]').forEach(b=>b.onclick=()=>{const pid=b.dataset.id;close();goalPicker('assist',pid)});
   }else{
    const eligible=on.filter(p=>p.id!==scorer);
    show(`<div class="row spread"><h2>🎯 SELECT ASSIST</h2><button class="ghost" data-close>✕</button></div><p class="muted">⚽ ${esc(name(scorer))} scores. Who assisted?</p><button class="button no-assist" id="noAssist">NO ASSIST — RECORD GOAL</button>${miniCards(eligible,'assist')}<button class="ghost" id="backToScorer">← CHANGE GOALSCORER</button>`);
    let committed=false;const commit=assist=>{if(committed)return;committed=true;push({type:'goal',player:scorer,...(assist?{assist}:{})});lastGoalUndo={matchId:m.id,eventId:m.events[m.events.length-1].id};eventFeedback(name(scorer)+' SCORES!','goal',pBy(scorer),true)};
    $('#noAssist').onclick=()=>commit(null);
    modal.querySelectorAll('[data-pick="assist"]').forEach(b=>b.onclick=()=>commit(b.dataset.id));
    $('#backToScorer').onclick=()=>{close();goalPicker('scorer')};
   }
  };
  goalPicker('scorer');return;
 }
 if(type==='penalty'){
  if(!on.length)return alert('There are no registered players currently on the pitch.');
  show(`<h2>🥅 PENALTY</h2><p class="muted">Select penalty taker (on pitch).</p>${miniCards(on,'scorer')}<label class="field section">Outcome<select id="penaltyOutcome"><option value="scored">Scored</option><option value="missed">Missed</option></select></label><div class="row section"><button class="button" id="confirmEvent">RECORD PENALTY</button><button class="ghost" data-close>CANCEL</button></div>`);
  selectable('scorer');$('#confirmEvent').onclick=()=>{const scorer=selected('scorer')[0];if(!scorer)return alert('Select a player first.');const scored=$('#penaltyOutcome').value==='scored';push({type:scored?'penalty-goal':'penalty-miss',player:scorer});eventFeedback(scored?name(scorer)+' SCORES!':'Penalty missed',scored?'goal':'normal',pBy(scorer))};return;
 }
 if(type==='sub'){
  if(!on.length||!bench.length)return alert('A substitution requires someone on the pitch and someone on the bench.');
  show(`<h2>🔄 MULTIPLE SUBSTITUTIONS</h2><p class="muted">Select players OFF, then select the same number ON. Pairs follow selection order shown in the review.</p><h3>PLAYERS OFF</h3>${miniCards(on,'off')}<h3 class="section">PLAYERS ON</h3>${miniCards(bench,'on')}<div class="section" id="subReview"></div><div class="row"><button class="button" id="confirmEvent">CONFIRM SUBSTITUTIONS</button><button class="ghost" data-close>CANCEL</button></div>`);
  const order={off:[],on:[]};for(const group of ['off','on'])document.querySelectorAll(`[data-pick="${group}"]`).forEach(b=>b.onclick=()=>{const arr=order[group],idx=arr.indexOf(b.dataset.id);if(idx>=0)arr.splice(idx,1);else arr.push(b.dataset.id);b.classList.toggle('selected');$('#subReview').innerHTML=`<p class="muted">${order.off.length} OFF · ${order.on.length} ON</p>`+order.off.map((pid,i)=>`<div class="subpair">${esc(name(pid))} → ${esc(order.on[i]?name(order.on[i]):'Select replacement')}</div>`).join('')});
  $('#confirmEvent').onclick=()=>{if(!order.off.length||order.off.length!==order.on.length)return alert('Select an equal number of players OFF and ON.');const t=elapsed(m);order.off.forEach((off,i)=>m.events.push({id:id(),type:'sub',off,on:order.on[i],minute:t,order:Date.now()+i}));save();close();render();eventFeedback(`${order.off.length} substitution${order.off.length===1?'':'s'} recorded`)};return
 }
 if(type==='pitch'){
  show(`<h2>👥 ADJUST PLAYERS</h2><p class="muted">Change numbers on the pitch without making a substitution.</p><h3>OUR TEAM — ${on.length} PLAYING</h3><div class="row"><button class="ghost" id="ourAdd">+ ADD TO PITCH</button><button class="ghost" id="ourRemove">− REMOVE FROM PITCH</button></div><div id="ourPicker"></div><h3 class="section">OPPOSITION — <span id="oppCount">${opponentCount(m)}</span> PLAYING</h3><div class="row"><button class="ghost" id="oppRemove">− REMOVE</button><button class="ghost" id="oppAdd">+ ADD</button></div><div class="row section"><button class="ghost" data-close>DONE</button></div>`);
  const picker=(players,kind)=>{if(!players.length){$('#ourPicker').innerHTML='<p class="muted">No players available.</p>';return}$('#ourPicker').innerHTML=`<h3 class="section">${kind==='pitch-add'?'SELECT PLAYER TO ADD':'SELECT PLAYER TO REMOVE'}</h3>${miniCards(players,'adjust')}`;document.querySelectorAll('[data-pick="adjust"]').forEach(b=>b.onclick=()=>{push({type:kind,player:b.dataset.id});eventFeedback('Players on pitch updated')})};
  $('#ourAdd').onclick=()=>picker(bench,'pitch-add');$('#ourRemove').onclick=()=>picker(on,'pitch-remove');
  $('#oppAdd').onclick=()=>{push({type:'opp-add'});eventFeedback('Opposition player added')};$('#oppRemove').onclick=()=>{if(opponentCount(m)<=0)return alert('Opposition count cannot go below zero.');push({type:'opp-remove'});eventFeedback('Opposition player removed')};return
 }
}
function exportCard(p){if(!p)return;const safe=s=>esc(s);const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="1350" viewBox="0 0 900 1350"><defs><linearGradient id="g" x2="1" y2="1"><stop stop-color="#234a42"/><stop offset="1" stop-color="#07111f"/></linearGradient><radialGradient id="gl"><stop stop-color="#b8ff3b" stop-opacity=".38"/><stop offset="1" stop-color="#b8ff3b" stop-opacity="0"/></radialGradient></defs><rect width="900" height="1350" rx="68" fill="url(#g)"/><circle cx="460" cy="500" r="480" fill="url(#gl)"/><path d="M-40 860 L750 70 M80 1230 L950 340" stroke="#b8ff3b" stroke-opacity=".12" stroke-width="90"/><rect x="20" y="20" width="860" height="1310" rx="58" fill="none" stroke="#b8ff3b" stroke-width="12"/><rect x="52" y="52" width="796" height="1246" rx="38" fill="none" stroke="#caff83" stroke-opacity=".55" stroke-width="3"/><text x="450" y="160" font-family="Arial,sans-serif" font-size="34" font-weight="bold" text-anchor="middle" fill="#b8ff3b">${safe(db.club.name.toUpperCase())}</text><text x="450" y="795" font-family="Impact,Arial,sans-serif" font-size="570" font-weight="900" text-anchor="middle" fill="#d7ff8b">${safe(p.number)}</text><text x="450" y="870" font-family="Arial,sans-serif" font-size="27" letter-spacing="8" text-anchor="middle" fill="#d4e9e3">${safe((p.position||'PLAYER').toUpperCase())}</text><path d="M90 950 H810" stroke="#b8ff3b" stroke-opacity=".5" stroke-width="3"/><text x="450" y="1060" font-family="Arial,sans-serif" font-size="75" font-weight="900" text-anchor="middle" fill="white" textLength="${Math.min(750,Math.max(240,p.name.length*45))}" lengthAdjust="spacingAndGlyphs">${safe(p.name.toUpperCase())}</text><text x="450" y="1170" font-family="Brush Script MT,cursive" font-style="italic" font-size="95" text-anchor="middle" fill="#fff3cc">${safe(p.name)}</text><text x="450" y="1260" font-family="Arial,sans-serif" font-size="26" letter-spacing="5" text-anchor="middle" fill="#b8ff3b">MATCHDAY MASTERS</text></svg>`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));a.download=p.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-player-card.svg';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}

setInterval(()=>{const m=current();if(page==='live'&&m&&$('#clock'))$('#clock').textContent=formatClock(elapsed(m));const recoveryClock=document.querySelector('[data-recovery-clock]');const ongoing=db.matches.find(x=>x.status==='live');if(recoveryClock&&ongoing)recoveryClock.textContent=formatClock(elapsed(ongoing))},1000);if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));initCloud();
